import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","description":"学习 It is/was…that 强调句，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 21 William S. Hart and the early 'Western' film","description":"学习 It is/was…that 强调句，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 It is/was…that 强调句，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 20 Snake poison","link":"/life/english/new-concept/book-4/unit-03/lesson-020"},"next":{"text":"第四册：流利英语 · Lesson 22 Knowledge and progress","link":"/life/english/new-concept/book-4/unit-03/lesson-022"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 20 Snake poison","link":"/life/english/new-concept/book-4/unit-03/lesson-020"},"next":{"text":"第四册：流利英语 · Lesson 22 Knowledge and progress","link":"/life/english/new-concept/book-4/unit-03/lesson-022"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-03/lesson-021.md","filePath":"life/english/new-concept/book-4/unit-03/lesson-021.md"}`),s={name:"life/english/new-concept/book-4/unit-03/lesson-021.md"};function l(o,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-21-william-s-hart-and-the-early-western-film" tabindex="-1">第四册：流利英语 · Lesson 21 William S. Hart and the early &#39;Western&#39; film <a class="header-anchor" href="#第四册-流利英语-·-lesson-21-william-s-hart-and-the-early-western-film" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 21 William S. Hart and the early &#39;Western&#39; film&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元 3</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>借早期西部片与银幕人物讨论艺术形象如何被塑造，区分电影呈现的边疆与复杂的历史现实。学习把演员、角色和叙事风格分别描述，避免把类型片的惯例当作真实社会全貌。重点使用强调句突出影响观众判断的具体因素。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>portrayal</td><td>/pɔːˈtreɪəl/</td><td>n.</td><td>描绘</td><td>a screen portrayal</td></tr><tr><td>genre</td><td>/ˈʒɒnrə/</td><td>n.</td><td>类型</td><td>a film genre</td></tr><tr><td>frontier</td><td>/ˈfrʌntɪə/</td><td>n.</td><td>边疆</td><td>a frontier setting</td></tr><tr><td>audience</td><td>/ˈɔːdiəns/</td><td>n.</td><td>观众</td><td>a modern audience</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>on screen — 在银幕上</li><li>be shaped by — 受到某因素塑造</li></ul><h2 id="语法讲解-it-is-was-that-强调句" tabindex="-1">语法讲解：It is/was…that 强调句 <a class="header-anchor" href="#语法讲解-it-is-was-that-强调句" aria-label="Permalink to &quot;语法讲解：It is/was…that 强调句&quot;">​</a></h2><p>强调句用 It is/was + 被强调部分 + that/who + 其余成分，常强调主语、宾语或状语。It was the lighting that changed the scene. 去掉 It was 与 that 后可还原 The lighting changed the scene。不要把所有 it is…that 都当强调句：It is clear that… 中 it 是形式主语，clear 不能作为原句成分还原。强调时间通常仍用 that，而不是 when。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>It was the actor’s silence that made the final scene so tense.</p></blockquote><p>正是演员的沉默让最后一幕如此紧张。</p><p>the actor’s silence 是被强调主语；还原为 The actor’s silence made the final scene so tense。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>It was in 1910 when… 若意在强调时间，应使用 that；when 另可引导关系或时间从句。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读 the actor’s silence，弱读 it was 与 that；同一句改强调 final scene，体会信息焦点随重音变化。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>It was the long pause that caught my attention. The actor looked towards the empty doorway without moving. This small gesture created more tension than a dramatic speech would have done.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句评论一段自选无声电影片段，说明哪种表演手段影响了你。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>强调句提出观察焦点，具体动作提供依据，比较句说明效果。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>还原示例为普通陈述句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> The actor’s silence made the final scene so tense.</p><p><strong>解析：</strong> 去掉强调框架后主干完整。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>填空：It was the music ___ changed my impression.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> that</p><p><strong>解析：</strong> 强调主语使用 that。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>It is surprising that she left. 是强调句吗？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不是。</p><p><strong>解析：</strong> it 为形式主语，that 从句为真正主语，不能还原为 surprising she left。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：It is/was…that 强调句。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-03/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-03/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-03/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">上一课</a> · <a href="/life/english/new-concept/book-4/unit-03/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-03/lesson-022">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(s,[["render",l]]);export{u as __pageData,m as default};
